let state,plan,runId=null,heat,lastStartKey=null,selectedPoint=null,traceContext=null;const $=id=>document.getElementById(id);const pretty=o=>JSON.stringify(o,null,2);const id=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();
let ready=false,dirty=false,previewing=false,starting=false,refreshing=false,editVersion=0,heatVersion=0;
const nextSimulation=document.createElement('button');nextSimulation.id='nextSimulation';nextSimulation.textContent='新建下一次模拟';$('start').after(nextSimulation);
function simulationBody(){return {origin:'SIMULATED_DEVELOPMENT',plan_sha256:plan.plan_sha256,seed:Number($('seed').value),strategy:$('strategy').value,unknown_rate:Number($('unknownRate').value)}}
function simulationScope(body){return 'lab_simulation_key_v2_'+JSON.stringify(body)}
function resetSimulationIntent(){localStorage.removeItem(simulationScope(simulationBody()));lastStartKey=null}
function clearTrace(){selectedPoint=null;traceContext=null;$('pointTrace').textContent='点击格点查看当前图的最新状态；模拟与真实回放分别追溯'}
function renderTrace(){if(!selectedPoint||!heat)return;let c=heat.cells.find(x=>x.point_id===selectedPoint);$('pointTrace').textContent=c?pretty({...c,view_context:{plan_sha256:plan.plan_sha256,run_id:runId,origin:runId?'SIMULATED_DEVELOPMENT':'AUDITED_REAL_REPLAY'}}):'当前图不包含所选格点'}
nextSimulation.onclick=async()=>{if(!ready||starting||previewing||state.runs.some(r=>r.state==='RUNNING'))return;resetSimulationIntent();runId=null;localStorage.removeItem('lab_run_id');clearTrace();await showHeat();$('runState').textContent='下一次模拟待启动；当前图为历史真实回放';$('error').style.display='none';controls()};
const planFields=['d','s','byte','bit','phases','widths','repeats','budget','target'];
function controls(){ $('start').disabled=!ready||dirty||previewing||starting;$('preview').disabled=!ready||previewing||starting;nextSimulation.disabled=!ready||previewing||starting||state.runs.some(r=>r.state==='RUNNING');for(let name of planFields)$(name).disabled=!ready||starting;$('draftState').textContent=previewing?'正在生成预览，启动已禁用':dirty?'参数已修改，尚未提交；请重新生成预览后启动':'表单与当前不可变计划一致'; }
function restoreForm(){for(let name of ['d','s','byte','bit'])$(name).value=plan.fixed[name];$('phases').value=plan.phases.join(',');$('widths').value=plan.widths.join(',');$('repeats').value=plan.repeats;$('budget').value=plan.explicit_limit;let value=plan.targets.join(',');if(!Array.from($('target').options).some(o=>o.value===value))$('target').add(new Option(plan.targets.join(' + '),value));$('target').value=value;dirty=false;controls();}
for(let name of planFields){for(let event of ['input','change'])$(name).addEventListener(event,()=>{dirty=true;editVersion++;controls()});}
function error(e){$('error').textContent=String(e.message||e);$('error').style.display='block';setTimeout(()=>$('error').style.display='none',8000)}
async function get(url){let r=await fetch(url),v=await r.json();if(!r.ok)throw Error(v.error||r.status);return v}
async function post(url,b){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Lab-Token':state.csrf},body:JSON.stringify(b)}),v=await r.json();if(!r.ok)throw Error(v.error);return v}
function planInfo(){let legal=plan.cells.filter(c=>c.legal).length;$('planSummary').textContent=`当前不可变计划：d=${plan.fixed.d} / s=${plan.fixed.s} / byte=${plan.fixed.byte} / bit=${plan.fixed.bit} / count=${plan.fixed.count}\nphase=[${plan.phases}] / width=[${plan.widths}]\n每点重复 ${plan.repeats} / 判据 ${plan.targets.join(' + ')}\n合法 ${legal} / 非法 ${plan.cells.length-legal}\nCONFIG ${plan.config_starts} + 参照 ${plan.control_starts} + ITEM ${plan.requests.length} = ${plan.required_starts} 次\n上限 ${plan.explicit_limit}（软件建议，未授予硬件预算）\n计划 SHA256 ${plan.plan_sha256}\n载荷 SHA256 ${plan.payload_sha256}`}
async function showHeat(){let p=plan.plan_sha256,r=runId,v=++heatVersion;let result=await get('/api/heatmap?plan='+p+(r?'&run='+r:''));if(v!==heatVersion||p!==plan.plan_sha256||r!==runId)return;let context=p+'|'+(r||'REAL_REPLAY');if(traceContext!==context){clearTrace();traceContext=context}heat=result;renderHeat();renderTrace()}
function renderHeat(){if(!heat)return;let ps=[...new Set(heat.cells.map(c=>c.phase))],ws=[...new Set(heat.cells.map(c=>c.width))];for(let [div,t]of[['Bheat','B_frame_correct'],['Sheat','STM_business_success']]){let table=document.createElement('table');table.innerHTML='<tr><th>相位↓ / 宽度→</th>'+ws.map(w=>`<th>${w}</th>`).join('')+'</tr>';for(let p of ps){let tr=document.createElement('tr');tr.innerHTML=`<th>${p}</th>`;for(let w of ws){let c=heat.cells.find(x=>x.phase===p&&x.width===w),s=c.targets[t],td=document.createElement('td');td.className='cell '+(!c.legal?'illegal':s.unknown?'unknown':s.fraction===null?'unmeasured':s.fraction>=.5?'success':'failure');td.textContent=!c.legal?'非法':s.unknown?'? '+s.unknown:s.fraction===null?'未测':s.success+'/'+s.valid;let pred=heat.predictions.find(x=>x.point_id===c.point_id&&x.target===t);if($('prediction').checked&&pred&&s.valid===0&&c.legal){td.classList.add('predicted');td.textContent='预测 '+pred.estimate.toFixed(2)}td.onclick=()=>{selectedPoint=c.point_id;renderTrace()};tr.appendChild(td)}table.appendChild(tr)}$(div).replaceChildren(table)}$('coverage').textContent=`声明合法网格 ${heat.coverage.legal}；有测量 ${heat.coverage.measured}；含 UNKNOWN ${heat.coverage.unknown}。不同 d/s 分图。${runId?'此图全为开发模拟。':'真实数据仅有稀疏点，不是完整边界。'}`;$('origin').textContent=runId?'开发模拟（非实测）':'已审核真实证据回放'}
function imageReport(){if(!state)return;let method=$('imageMethod').value,m=state.image_metrics,report=m.methods[method];$('repairImage').src='/artifacts/image_repair/'+method+'/data.png';$('modifiedImage').src='/artifacts/image_repair/'+method+'/modified.png';$('uncertainImage').src='/artifacts/image_repair/'+method+'/uncertain.png';$('missingImage').src='/artifacts/image_repair/'+method+'/missing.png';$('imageReport').innerHTML='<table><tr><th>输入/处理</th><th>错误像素</th><th>MAE</th><th>整图 CONFIG SHA</th></tr>'+[['未修复 B',m.baselines.B],['未修复 A',m.baselines.A],['未修复 STM',m.baselines.STM],['无修复 CRC 择优',m.methods.crc_select],[method,report]].map(([k,v])=>`<tr><td>${k}</td><td>${v.error_pixels}</td><td>${Number(v.MAE).toFixed(5)}</td><td>${v.receiver_config_SHA_verified===true?'匹配':v.receiver_config_SHA_verified===false?'未匹配':'—'}</td></tr>`).join('')+'</table><p>相对 B 错误和 MAE 同时改善：'+(report.improves_B_error_and_MAE?'是':'未达成')+'；优于无修复择优基线：'+(report.improves_no_repair_CRC_selection?'是':'未达成')+'</p>'}
function algorithmReport(){if(!state.algorithms){$('algorithmReport').textContent='尚未生成开发对照，请运行 algorithm-demo。';return}let html='';for(let [target,r]of Object.entries(state.algorithms.targets)){html+='<h3>'+target+'</h3><table><tr><th>独立合成组/种子</th><th>网格总次数</th><th>选点总次数</th><th>离散边界误差 tick</th><th>同精度减少次数</th><th>算法计算秒</th></tr>';for(let x of r.runs)html+=`<tr><td>${x.seed}</td><td>${x.baseline_total_starts}</td><td>${x.selected_total_starts}</td><td>${x.boundary_error.max_discrete_boundary_tick_error}</td><td>${x.acceleration_goal_met_in_simulation?'是（仅模拟）':'未达成'}</td><td>${x.algorithm_compute_seconds.toFixed(5)}</td></tr>`;html+='</table>'}$('algorithmReport').innerHTML=html}
async function refresh(){if(refreshing)return;refreshing=true;try{state=await get('/api/state');if(!plan){plan=state.default_plans['3'];let saved=localStorage.getItem('lab_plan_hash');if(saved){try{plan=await get('/api/plan?hash='+saved)}catch(e){}}runId=localStorage.getItem('lab_run_id')||null;if(runId&&!state.runs.some(r=>r.run_id===runId&&r.plan_sha256===plan.plan_sha256))runId=null;let restoredRun=state.runs.find(r=>r.run_id===runId);if(restoredRun&&typeof restoredRun.seed==='number'){$('seed').value=restoredRun.seed;$('strategy').value=restoredRun.strategy;$('unknownRate').value=restoredRun.unknown_rate}lastStartKey=localStorage.getItem('lab_start_key_'+plan.plan_sha256);ready=true;restoreForm();planInfo();await showHeat();imageReport();algorithmReport()}let r=state.runs.find(x=>x.run_id===runId);if(r){$('runState').textContent=`${r.state} · 模拟已占用 ${r.used_starts} / ${plan.explicit_limit} · 取消未执行 ${r.cancelled_unstarted} · ${r.reason||'按预声明候选执行'}`;await showHeat()}$('traceReport').textContent=pretty({execution:state.execution,evidence:state.evidence});$('runs').textContent=state.runs.map(r=>r.run_id+' | '+r.state+' | '+r.origin+' | used='+r.used_starts).join('\n')}catch(e){error(e)}finally{refreshing=false;controls()}}
$('preview').onclick=async()=>{if(!ready||previewing||starting)return;let version=editVersion;previewing=true;controls();try{let next=await post('/api/plan',{phases:$('phases').value.split(',').map(Number),widths:$('widths').value.split(',').map(Number),d:Number($('d').value),s:Number($('s').value),byte:Number($('byte').value),bit:Number($('bit').value),repeats:Number($('repeats').value),budget:Number($('budget').value),targets:$('target').value.split(',')});if(version!==editVersion){dirty=true;return}plan=next;runId=null;localStorage.removeItem('lab_run_id');lastStartKey=id();localStorage.setItem('lab_plan_hash',plan.plan_sha256);localStorage.setItem('lab_start_key_'+plan.plan_sha256,lastStartKey);restoreForm();resetSimulationIntent();clearTrace();planInfo();$('runState').textContent='新计划已预览，尚未启动';await showHeat()}catch(e){dirty=true;error(e)}finally{previewing=false;controls()}};
$('start').onclick=async()=>{if(!ready||dirty||previewing||starting)return;starting=true;controls();try{let body=simulationBody(),scope=simulationScope(body);lastStartKey=localStorage.getItem(scope)||id();localStorage.setItem(scope,lastStartKey);localStorage.setItem('lab_plan_hash',plan.plan_sha256);let r=await post('/api/start',{...body,idempotency_key:lastStartKey});$('error').style.display='none';runId=r.run_id;localStorage.setItem('lab_run_id',runId);await refresh()}catch(e){error(e)}finally{starting=false;controls()}};
$('stop').onclick=async()=>{try{if(!runId)throw Error('没有当前模拟运行');await post('/api/stop',{run_id:runId,idempotency_key:id()});await refresh()}catch(e){error(e)}};
$('replay').onclick=async()=>{try{runId=null;localStorage.removeItem('lab_run_id');clearTrace();await showHeat();$('runState').textContent='离线真实证据回放，不执行硬件'}catch(e){error(e)}};
$('submitMainline').onclick=async()=>{try{await post('/api/submit-mainline',{plan_sha256:plan.plan_sha256})}catch(e){error(e)}};
$('exportCSV').onclick=()=>window.open('/api/export.csv?plan='+plan.plan_sha256+(runId?'&run='+runId:''));document.querySelectorAll('.downloadSVG').forEach(b=>b.onclick=()=>window.open('/api/export.svg?plan='+plan.plan_sha256+'&target='+b.dataset.target+(runId?'&run='+runId:'')));
$('prediction').onchange=renderHeat;$('imageMethod').onchange=imageReport;document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.tab));document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('on',x===b))});controls();refresh();setInterval(refresh,1500);
